# So x has PAF values in {-3, 1}. We need x+y PAF = -2 for all k=1..12.
# If PAF_x(k) = 1, need PAF_y(k) = -3. If PAF_x(k) = -3, need PAF_y(k) = 1.
# So y should be "complementary": PAF_y(k) = 1 when PAF_x(k) = -3, etc.
# Try y based on non-residues or a different quadratic character construction.
# Try y[i] = leg(i+shift) or -leg(i), etc.

def paf(s,k):
    n=len(s)
    return sum(s[i]*s[(i+k)%n] for i in range(n))

def leg(i,p=13):
    QR={1,3,4,9,10,12}
    if i%p==0: return 1
    return 1 if i%p in QR else -1

x=[leg(i) for i in range(13)]
# try all sign flips of position 0 and all shifts, maybe mixed with negation
