    for neg in [1,-1]:
        for shift in range(13):
            y=[neg*leg((i+shift)) for i in range(13)]
            y[0]=sign0  # override
            # actually don't override, try as is
            y=[neg*leg((i+shift)) for i in range(13)]
            if sum(y)!=1: continue
            ok=all(paf(x,k)+paf(y,k)==-2 for k in range(1,7))
            if ok:
